17	    public async Task<LessonDetailResponse?> GetLessonAsync(string lessonId, CancellationToken ct = default)
18	    {
19	        var aiResult = await db.AiResults
20	            .AsNoTracking()
21	            .Where(r => r.LessonId == lessonId)
22	            .OrderByDescending(r => r.CreatedAt)
23	            .FirstOrDefaultAsync(ct);
24	
25	        if (aiResult is not null)
26	        {
27	            string? videoPath = CourseHelper.BuildVideoKey(aiResult.Semester, aiResult.CourseId, aiResult.ClassSection, aiResult.GeneratedAt.Value);
28	
29	            var course = await db.Courses
30	                .AsNoTracking()
31	                .Where(c => c.CourseKey == aiResult.CourseKey)
32	                .Select(c => new { c.Name, c.NameEn, c.Section })
33	                .FirstOrDefaultAsync(ct);
34	
35	            var expectedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.ExpectedGroupsJson) ?? [];
36	            var completedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.CompletedGroupsJson) ?? [];
37	            var missingGroups = JsonSerializer.Deserialize<List<string>>(aiResult.MissingGroupsJson) ?? [];
38	            var duration = aiResult.WindowSeconds > 0 && aiResult.TotalWindows > 0
39	                                  ? (int?)(aiResult.WindowSeconds * aiResult.TotalWindows)
40	                                  : null;
41	
42	            var metadata = new LessonMetadataDto(
43	                Semester: aiResult.Semester,
44	                CourseId: aiResult.CourseId,
45	                CourseKey: aiResult.CourseKey,
46	                CourseName: course?.Name ?? "",
47	                CourseNameEn: course?.NameEn,
48	                LessonId: lessonId,
49	                ClassSection: aiResult.ClassSection,
50	                Week: aiResult.Week,
51	                RecordDate: aiResult.RecordDate?.ToString("yyyy-MM-dd") ?? "",
52	                LessonDate: aiResult.LessonDate?.ToString("yyyy-MM-dd") ?? "",
53	                CreatedAt: aiResult.CreatedAt.ToString("o"),
54	                GeneratedAt: aiResult.GeneratedAt?.ToString("o"),
55	                ExpectedGroups: expectedGroups,
56	                CompletedGroups: completedGroups,
57	                MissingGroups: missingGroups,
58	                Duration: duration,
59	                VideoPath: aiResult.VideoPath,
60	                IsScreenshotGenerated: aiResult.IsScreenshotGenerated
61	            );
62	
63	            var result = await BuildResultFromDbAsync(lessonId, ct);
64	
65	            return new LessonDetailResponse(Metadata: metadata, Result: result);
66	        }
67	
68	        return null;
69	    }
