71	    public async Task<LatestLessonsResponse> GetLatestLessonsAsync(int limit, CancellationToken ct = default)
72	    {
73	        var safeLimit = Math.Clamp(limit, 1, 20);
74	
75	        var latestResults = await db.AiResults
76	            .AsNoTracking()
77	            .Where(r => r.IsScreenshotGenerated)
78	            .OrderByDescending(r => r.GeneratedAt.HasValue)
79	            .ThenByDescending(r => r.GeneratedAt)
80	            .ThenByDescending(r => r.CreatedAt)
81	            .Take(safeLimit)
82	            .Select(r => new
83	            {
84	                r.LessonId,
85	                r.CourseKey,
86	                r.CourseId,
87	                r.ClassSection,
88	                r.LessonDate,
89	                r.GeneratedAt,
90	                r.CreatedAt
91	            })
92	            .ToListAsync(ct);
93	
94	        if (latestResults.Count == 0)
95	            return new LatestLessonsResponse([]);
96	
97	        var courseKeys = latestResults.Select(r => r.CourseKey).Distinct().ToList();
98	        var courses = await db.Courses
99	            .AsNoTracking()
100	            .Where(c => courseKeys.Contains(c.CourseKey))
101	            .Select(c => new { c.CourseKey, c.Name, c.NameEn, c.Section, c.SchedulesJson })
102	            .ToDictionaryAsync(c => c.CourseKey, ct);
103	
104	        var lessons = latestResults.Select(result =>
105	        {
106	            courses.TryGetValue(result.CourseKey, out var course);
107	
108	            return new LatestLessonDto(
109	                LessonId: result.LessonId,
110	                CourseKey: result.CourseKey,
111	                CourseName: course?.Name ?? "",
112	                CourseNameEn: course?.NameEn,
113	                CourseId: result.CourseId,
114	                CourseSection: result.ClassSection,
115	                CourseSchedule: course?.SchedulesJson is null
116	                    ? []
117	                    : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [],
118	                LessonDate: result.LessonDate?.ToString("yyyy-MM-dd"),
119	                GeneratedAt: result.GeneratedAt?.ToString("o"),
120	                CreatedAt: result.CreatedAt.ToString("o")
121	            );
122	        }).ToList();
123	
124	        return new LatestLessonsResponse(lessons);
125	    }
