5	public class Saml2CookieManager : ICookieManager
6	{
7	    private readonly ChunkingCookieManager _inner = new ChunkingCookieManager();
8	    private readonly PathString _saml2CookiePath;
9	
10	    public Saml2CookieManager(string? baseUrlPath)
11	    {        
12	        _saml2CookiePath = string.IsNullOrEmpty(baseUrlPath)
13	            ? new PathString("/")
14	            : new PathString("/" + baseUrlPath);
15	    }
16	
17	    public string? GetRequestCookie(HttpContext context, string key)
18	    {
19	        return _inner.GetRequestCookie(context, key);
20	    }
21	
